from __future__ import absolute_import

from selenium.common.exceptions import TimeoutException
from selenium.webdriver.common.by import By
from taf.selenium.sbts.pages import v23r3, v23r2
from taf.selenium.sbts.pages.modals import PowerResetModal
from taf.selenium.sbts.pages.navigatable_page import NavigatablePage
from taf.selenium.sbts.pages.panels.view import ViewPanel


class Procedures(v23r3.Procedures):
    def __init__(self, driver):
        super(Procedures, self).__init__(driver)
        self._bts_power_reset = BtsPowerRestPage(driver)
        self._baseband_power_reset = BasebandModulePowerResetPage(driver)

    @property
    def baseband_power_reset(self):
        return self._baseband_power_reset


class BtsPowerRestPage(v23r3.procedures.BtsPowerRestPage):
    _MENU_ROUTE_LIST = ['Procedures', 'Power Reset', 'BTS Power Reset']

    def __init__(self, driver):
        super(BtsPowerRestPage, self).__init__(driver)
        self._view_panel = BtsPowerRestPageViewPanel(driver)

    def power_reset(self, timeout=60, with_snapshot_collection=False, with_graceful=False):
        return self._view_panel.power_reset(timeout, with_snapshot_collection, with_graceful)


class BtsPowerRestPageViewPanel(v23r2.procedures.BtsPowerRestPageViewPanel):
    def __init__(self, driver):
        super(BtsPowerRestPageViewPanel, self).__init__(driver)

    def power_reset(self, timeout=60, with_snapshot_collection=False, with_graceful=False):
        if with_snapshot_collection:
            self.click_enabled_element((By.XPATH, self.POWER_RESET_WITH_SNAPSHOT_COLLECTION), timeout)
        else:
            self.click_enabled_element((By.XPATH, self.POWER_RESET), timeout)

        self.click_enabled_element((By.XPATH, self.EXECUTE), timeout)
        power_reset = PowerResetModal(self.driver)
        power_reset.wait_until_power_reset_modal_appear(timeout)
        power_reset.execute(with_graceful, timeout)
        self.wait_for_visibility_by_xpath(self.POWER_RESET_STATUS, timeout)
        self.wait_for_invisibility(self.POWER_RESET_STATUS, timeout)
        try:
            return self.get_text_by_xpath(self.RESET_STATUS, 5)
        except TimeoutException:
            return self.STARTING_POWER_RESET


class BasebandModulePowerResetPage(NavigatablePage):
    _MENU_ROUTE_LIST = ['Procedures', 'Power Reset', 'Baseband Module Power Reset']

    def __init__(self, driver):
        super(BasebandModulePowerResetPage, self).__init__(driver)
        self._view_panel = BasebandModulePowerResetPageViewPanel(driver)

    def baseband_power_reset(self, baseband_unit, with_graceful=False, timeout=300):
        self._view_panel.baseband_power_reset(baseband_unit, with_graceful, timeout)

    def get_units_to_be_reset(self):
        return self._view_panel.get_units_to_be_reset()

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST


class BasebandModulePowerResetPageViewPanel(ViewPanel):
    _BASEBAND_UNIT = '//li[div/div[text()="{}"]]'
    _UNIT_LIST = '//*[@class="bb-power-reset-list"]//li'
    _EXECUTE = '//*[@class="bb-power-reset-excute"]//button'
    _STARTING_POWER_RESET = 'Starting power reset'
    _POWER_RESET_STATUS = '//span[contains(text(), "{}")]'.format(_STARTING_POWER_RESET)
    _RESET_STATUS = '//ot-instruction//span'

    def __init__(self, driver):
        super(BasebandModulePowerResetPageViewPanel, self).__init__(driver)

    def baseband_power_reset(self, baseband_unit, with_graceful=False, timeout=300):
        self.wait_for_visibility_by_xpath(self._BASEBAND_UNIT.format(baseband_unit), timeout)
        self.click_enabled_element((By.XPATH, self._BASEBAND_UNIT.format(baseband_unit)), timeout)
        self.click_enabled_element((By.XPATH, self._EXECUTE), timeout)
        power_reset = PowerResetModal(self.driver)
        power_reset.wait_until_power_reset_modal_appear(timeout)
        power_reset.execute(with_graceful, timeout)
        self.wait_for_visibility_by_xpath(self._POWER_RESET_STATUS, timeout)
        self.wait_for_invisibility(self._POWER_RESET_STATUS, timeout)
        return self.get_text_by_xpath(self._RESET_STATUS, 5)

    def get_units_to_be_reset(self):
        self.wait_for_visibility_by_xpath(self._UNIT_LIST)
        unit_list = []
        for elem in self.driver.find_elements_by_xpath(self._UNIT_LIST):
            unit_list.append(elem.text.strip())
        return unit_list
